-- Catálogo de medicinas (187 presentaciones, 16 grupos), incluye crónicas: insulina, levodopa, anticoagulantes, etc.
-- uid FE-00001... es PROVISIONAL: no son códigos reales de Farmaenlace.
-- efectos_secundarios: información general por principio activo; validar con un químico farmacéutico.
-- laboratorio: marca/fabricante original más conocido del principio activo ("Genfar" = genérico por defecto).
--   NO viene del catálogo de Farmaenlace; confirmar antes de presentarlo como dato real.
-- La tabla se crea en db/init/001_schema.sql.

ON CONFLICT (uid) DO UPDATE SET
    nombre = EXCLUDED.nombre, concentracion = EXCLUDED.concentracion, unidad = EXCLUDED.unidad,
    grupo = EXCLUDED.grupo, efectos_secundarios = EXCLUDED.efectos_secundarios, laboratorio = EXCLUDED.laboratorio;
